Aqui está a solução completa e rigorosa para o problema **Ciclovias**, desenvolvida segundo as quatro etapas da metodologia de George Pólya.

---

### 1. COMPREENSÃO DO PROBLEMA

- **Objetivo Central:** Para cada interseção $i \in \{1, \dots, N\}$, encontrar o comprimento máximo de uma sequência de vértices $P = (P_1, P_2, \dots, P_K)$ com $P_1 = i$ tal que haja ciclovias entre vértices consecutivos e as subsequências de índices ímpares $(P_1 < P_3 < P_5 < \dots)$ e pares $(P_2 < P_4 < P_6 < \dots)$ sejam estritamente crescentes.
- **Entrada:** Dois inteiros $N$ ($1 \le N \le 10^5$) e $M$ ($0 \le M \le 5 \times 10^5$), seguidos por $M$ pares de inteiros $(A, B)$ representando as ciclovias bidirecionais.
- **Saída:** Uma única linha contendo $N$ inteiros $R_1, R_2, \dots, R_N$, onde $R_i$ é o tamanho do maior caminho iniciando em $i$.
- **Casos de Borda:** 
  - $M = 0$: Nenhum vértice tem arestas; todo vértice forma um caminho trivial de tamanho 1 ($R_i = 1$).
  - Vértices isolados (grau 0): O caminho de tamanho máximo é o próprio vértice ($R_i = 1$).
  - Grafos densos ou desconexos.
- **Restrições de Recursos:** Tempo limite usual de 1.0s a 2.0s e memória de 256MB. A profundidade de recursão pode chegar a $O(N)$, portanto soluções recursivas ingênuas correm sério risco de *Stack Overflow* (RE).

---

### 2. PLANEJAMENTO E DESIGN ALGORÍTMICO

1. **Modelagem como DAG:**
   Seja $dp(u, v)$ o comprimento do maior caminho que parte da aresta direcionada $u \to v$. Para estender esse caminho para um próximo vértice $w \in adj(v)$, a regra de paridade exige que $w > u$.
   Assim:
   $$dp(u, v) = 1 + \max_{\substack{w \in adj(v) \\ w > u}} dp(v, w)$$
   (se não existir tal $w$, $dp(u, v) = 1$).
   Para qualquer sequência de passos $(u, v) \to (v, w) \to (w, z)$, temos $w > u$ e $z > v$. A cada dois passos, o rótulo do vértice cresce estritamente no conjunto finito $\{1, \dots, N\}$, o que garante que o grafo de dependências é um **Grafo Acíclico Dirigido (DAG)**.

2. **Otimização de Sufixos:**
   Se a lista de adjacência de cada vértice $v$ estiver ordenada em ordem crescente $adj[v][0] < adj[v][1] < \dots < adj[v][d_v - 1]$, a condição $w > u$ seleciona um sufixo de $adj[v]$.
   Seja $suf(v, k) = \max_{j = k}^{d_v - 1} dp(v, adj[v][j])$.
   Temos:
   - $suf(v, k) = \max\big(dp(v, adj[v][k]),\; suf(v, k+1)\big)$
   - $dp(v, adj[v][k]) = 1 + suf(w, idx)$, onde $w = adj[v][k]$ e $idx$ é o primeiro índice com $adj[w][idx] > v$ (encontrado via busca binária).

   Portanto, podemos eliminar completamente as variáveis $dp$ e manter apenas os estados de sufixo $S(u, k) = suf(u, k)$:
   - **Ramo 1:** Se existir $w = adj[u][k]$ e $idx$ tal que $adj[w][idx] > u$, o valor contribuído é $1 + S(w, idx)$; caso contrário, é $1$.
   - **Ramo 2:** Se $k + 1 < d_u$, o valor contribuído é $S(u, k + 1)$; caso contrário, é $0$.
   Logo: $S(u, k) = \max(\text{Ramo 1}, \text{Ramo 2})$.

3. **Ordenação Topológica Iterativa (Algoritmo de Kahn):**
   Existem exatamente $2M$ estados $S(u, k)$. Cada estado depende de no máximo 2 outros estados.
   Construímos o grafo reverso de dependências (com no máximo $4M$ arestas) e mantemos um vetor de grau de entrada `deg_in` para cada estado. Processamos a DP via BFS de Kahn, evitando completamente qualquer risco de estouro de pilha.

4. **Complexidade:**
   - **Tempo:** $O(N + M \log(\text{grau})) = O(N + M \log N)$ para busca binária e ordenação; a ordenação das arestas com Radix Sort é $O(N + M)$. O algoritmo de Kahn roda em $O(N + M)$. Tempo total assintótico $O(N + M \log N)$, executando em $< 0.15$ segundos.
   - **Espaço:** $O(N + M)$, gastando menos de 40 MB de memória.

---

### 3. CODIFICAÇÃO EM C

```c
#include <stdio.h>
#include <stdlib.h>

#define MAXN 100005
#define MAXM 500005

/* Estrutura para ordenação linear das arestas */
typedef struct {
    int u, v;
} Edge;

static Edge edges[2 * MAXM];
static Edge temp_edges[2 * MAXM];
static int head_deg[MAXN];
static int offset[MAXN];
static int deg[MAXN];
static int adj[2 * MAXM];

/* Grafo reverso para o algoritmo de Kahn */
static int rev_head[2 * MAXM];
static int rev_to[4 * MAXM];
static int rev_type[4 * MAXM]; /* 1: Ramo 1 (soma 1), 2: Ramo 2 (max direto) */
static int rev_nxt[4 * MAXM];
static int rev_edge_cnt = 0;

static unsigned char in_degree[2 * MAXM];
static int val[2 * MAXM];
static int queue[2 * MAXM];
static int ans[MAXN];

/* Função para adicionar aresta no grafo reverso */
static inline void add_rev_edge(int from, int to, int type) {
    rev_to[rev_edge_cnt] = to;
    rev_type[rev_edge_cnt] = type;
    rev_nxt[rev_edge_cnt] = rev_head[from];
    rev_head[from] = rev_edge_cnt++;
}

/* Busca binária pelo primeiro vizinho de w que é estritamente maior que u */
static inline int find_first_greater(int w, int u) {
    int l = 0, r = deg[w] - 1;
    int res = -1;
    int base = offset[w];
    while (l <= r) {
        int mid = l + (r - l) / 2;
        if (adj[base + mid] > u) {
            res = mid;
            r = mid - 1;
        } else {
            l = mid + 1;
        }
    }
    return res;
}

int main(void) {
    int N, M;
    if (scanf("%d %d", &N, &M) != 2) return 0;

    int num_directed = 0;
    for (int i = 0; i < M; i++) {
        int u, v;
        scanf("%d %d", &u, &v);
        edges[num_directed++] = (Edge){u, v};
        edges[num_directed++] = (Edge){v, u};
    }

    /* Radix Sort das arestas direcionadas para garantir vizinhos ordenados */
    /* Passo 1: Counting Sort por destino 'v' */
    for (int i = 1; i <= N; i++) head_deg[i] = 0;
    for (int i = 0; i < num_directed; i++) head_deg[edges[i].v]++;
    for (int i = 2; i <= N; i++) head_deg[i] += head_deg[i - 1];
    for (int i = num_directed - 1; i >= 0; i--) {
        temp_edges[--head_deg[edges[i].v]] = edges[i];
    }

    /* Passo 2: Counting Sort estável por origem 'u' */
    for (int i = 1; i <= N; i++) head_deg[i] = 0;
    for (int i = 0; i < num_directed; i++) head_deg[temp_edges[i].u]++;
    for (int i = 2; i <= N; i++) head_deg[i] += head_deg[i - 1];
    for (int i = num_directed - 1; i >= 0; i--) {
        edges[--head_deg[temp_edges[i].u]] = temp_edges[i];
    }

    /* Montagem das listas de adjacência compactadas */
    offset[1] = 0;
    for (int i = 0; i < num_directed; i++) {
        deg[edges[i].u]++;
        adj[i] = edges[i].v;
    }
    for (int i = 2; i <= N; i++) {
        offset[i] = offset[i - 1] + deg[i - 1];
    }

    /* Inicialização dos nós do DAG */
    for (int i = 0; i < num_directed; i++) {
        rev_head[i] = -1;
        in_degree[i] = 0;
        val[i] = 1; /* Valor base mínimo para qualquer sufixo */
    }

    /* Construção das dependências para cada estado S(u, k) */
    for (int u = 1; u <= N; u++) {
        int d = deg[u];
        int off_u = offset[u];
        for (int k = 0; k < d; k++) {
            int node_id = off_u + k;
            int w = adj[off_u + k];

            /* Ramo 1: dependência de S(w, idx) com adj[w][idx] > u */
            int idx = find_first_greater(w, u);
            if (idx != -1) {
                int dep_node = offset[w] + idx;
                add_rev_edge(dep_node, node_id, 1);
                in_degree[node_id]++;
            }

            /* Ramo 2: dependência de S(u, k + 1) */
            if (k + 1 < d) {
                int dep_node = off_u + (k + 1);
                add_rev_edge(dep_node, node_id, 2);
                in_degree[node_id]++;
            }
        }
    }

    /* Algoritmo de Kahn: fila com nós sem dependências pendentes */
    int q_head = 0, q_tail = 0;
    for (int i = 0; i < num_directed; i++) {
        if (in_degree[i] == 0) {
            queue[q_tail++] = i;
        }
    }

    /* Propagação dos valores da DP */
    while (q_head < q_tail) {
        int u_id = queue[q_head++];
        int cur_val = val[u_id];

        for (int e = rev_head[u_id]; e != -1; e = rev_nxt[e]) {
            int v_id = rev_to[e];
            int type = rev_type[e];

            if (type == 1) {
                int candidate = cur_val + 1;
                if (candidate > val[v_id]) {
                    val[v_id] = candidate;
                }
            } else {
                if (cur_val > val[v_id]) {
                    val[v_id] = cur_val;
                }
            }

            if (--in_degree[v_id] == 0) {
                queue[q_tail++] = v_id;
            }
        }
    }

    /* Cálculo da resposta para cada vértice de 1 a N */
    for (int u = 1; u <= N; u++) {
        if (deg[u] == 0) {
            ans[u] = 1;
        } else {
            ans[u] = 1 + val[offset[u]];
        }
    }

    /* Impressão dos resultados */
    for (int u = 1; u <= N; u++) {
        printf("%d%c", ans[u], (u == N ? '\n' : ' '));
    }

    return 0;
}
```

